import java.util.*;
import java.io.*;

public class p1096g_v4 {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        long[] base = new long[10];
        for (int i = 0; i < k; i++) {
            base[sc.nextInt()] = 1;
        }
        long[] res = recursivePower(base, n / 2);
        long total = 0;
        for (long val : res) {
            total = (total + val * val) % MOD;
        }
        System.out.println(total);
    }

    static long[] recursivePower(long[] base, long exponent) {
        if (exponent == 1) return base;
        if ((exponent & 1) == 1) {
            return FFT.multiplyPrecise(base, recursivePower(base, exponent - 1));
        }
        long[] half = recursivePower(base, exponent >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        static final int MAX_K = 21;
        static final int MAX_N = 1 << MAX_K;
        static double[] wR = new double[MAX_N];
        static double[] wI = new double[MAX_N];
        static double[] aR = new double[MAX_N];
        static double[] aI = new double[MAX_N];
        static int n, k, lastK = -1;
        static int[] bitReverse = new int[MAX_N];

        static void performTransform(boolean inverse) {
            if (lastK != k) {
                lastK = k;
                bitReverse[0] = 0;
                for (int i = 1, group = 0; i < n; i++) {
                    if ((i & (i - 1)) == 0) group++;
                    bitReverse[i] = bitReverse[i ^ (1 << group)] ^ (1 << (k - 1 - group));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double cosVal = Math.cos(angle);
                    double sinVal = Math.sin(angle);
                    int p2 = 1 << t;
                    int p3 = p2 << 1;
                    for (int j = p2, idx = p3; j < p3; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosVal - wI[j] * sinVal;
                        wI[idx + 1] = wR[j] * sinVal + wI[j] * cosVal;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                int rev = bitReverse[i];
                if (i < rev) {
                    double temp = aR[i];
                    aR[i] = aR[rev];
                    aR[rev] = temp;
                    temp = aI[i];
                    aI[i] = aI[rev];
                    aI[rev] = temp;
                }
            }
            if (inverse) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len) {
                    int wIndex = len;
                    for (int j = i + len, it = 0; it < len; it++, i++, j++) {
                        double tr = aR[j] * wR[wIndex] - aI[j] * wI[wIndex];
                        double ti = aR[j] * wI[wIndex] + aI[j] * wR[wIndex];
                        wIndex++;
                        aR[j] = aR[i] - tr;
                        aI[j] = aI[i] - ti;
                        aR[i] += tr;
                        aI[i] += ti;
                    }
                }
            }
        }

        static long[] multiply(long[] first, long[] second) {
            int len1 = first.length, len2 = second.length;
            for (k = 0, n = 1; n < len1 + len2 - 1; n <<= 1, k++) {}
            for (int i = 0; i < n; i++) {
                aR[i] = (i < len1) ? first[i] : 0;
                aI[i] = (i < len2) ? second[i] : 0;
            }
            performTransform(false);
            aR[n] = aR[0];
            aI[n] = aI[0];
            double scaleFactor = -1.0 / n / 4.0;
            for (int i = 0; i <= n - i; i++) {
                double r1 = aR[i] * aR[i] - aI[i] * aI[i];
                double i1 = 2 * aR[i] * aI[i];
                double r2 = aR[n - i] * aR[n - i] - aI[n - i] * aI[n - i];
                double i2 = -2 * aR[n - i] * aI[n - i];
                double nr = -i1 + i2;
                double ni = r1 - r2;
                aR[i] = nr * scaleFactor;
                aI[i] = ni * scaleFactor;
                aR[n - i] = aR[i];
                aI[n - i] = -aI[i];
            }
            performTransform(true);
            long[] result = new long[len1 + len2 - 1];
            for (int i = 0; i < result.length; i++) {
                result[i] = Math.round(aR[i]) % MOD;
            }
            return result;
        }

        static long[] multiplyPrecise(long[] first, long[] second) {
            long sqrtMod = (long) Math.sqrt(MOD);
            long[] low1 = new long[first.length];
            long[] high1 = new long[first.length];
            long[] low2 = new long[second.length];
            long[] high2 = new long[second.length];
            for (int i = 0; i < first.length; i++) {
                low1[i] = first[i] % sqrtMod;
                high1[i] = first[i] / sqrtMod;
            }
            for (int i = 0; i < second.length; i++) {
                low2[i] = second[i] % sqrtMod;
                high2[i] = second[i] / sqrtMod;
            }
            long[] r11 = multiply(low1, low2);
            long[] r12 = multiply(low1, high2);
            long[] r21 = multiply(high1, low2);
            long[] r22 = multiply(high1, high2);
            long[] result = new long[r11.length];
            for (int i = 0; i < result.length; i++) {
                long term1 = (sqrtMod * sqrtMod % MOD) * r22[i] % MOD;
                long term2 = sqrtMod * ((r12[i] + r21[i]) % MOD) % MOD;
                result[i] = (term1 + term2 + r11[i]) % MOD;
            }
            return result;
        }
    }
}
